import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.ArrayList;import java.util.Arrays;import java.util.PriorityQueue;import java.util.StringTokenizer;public class TestClass {static class Edge {int to, weight;Edge(int to, int weight) {this.to = to;this.weight = weight;}}static class Node implements Comparable<Node> {int id, dist;Node(int id, int dist) {this.id = id;this.dist = dist;}public int compareTo(Node other) {return Integer.compare(this.dist, other.dist);}}public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int m = Integer.parseInt(st.nextToken());int k = Integer.parseInt(st.nextToken());int start = Integer.parseInt(st.nextToken());int end = Integer.parseInt(st.nextToken());ArrayList<ArrayList<Edge>> adj = new ArrayList<ArrayList<Edge>>(n + 1);for (int i = 0; i <= n; i++) adj.add(new ArrayList<Edge>());for (int i = 0; i < m; i++) {st = new StringTokenizer(br.readLine());int u = Integer.parseInt(st.nextToken());int v = Integer.parseInt(st.nextToken());adj.get(u).add(new Edge(v, 1));adj.get(v).add(new Edge(u, 1));}for (int i = 0; i < k; i++) {st = new StringTokenizer(br.readLine());int u = Integer.parseInt(st.nextToken());int v = Integer.parseInt(st.nextToken());adj.get(u).add(new Edge(v, 2));adj.get(v).add(new Edge(u, 2));}int[] dist = new int[n + 1];Arrays.fill(dist, Integer.MAX_VALUE);dist[start] = 0;PriorityQueue<Node> pq = new PriorityQueue<Node>();pq.add(new Node(start, 0));while (!pq.isEmpty()) {Node curr = pq.poll();if (curr.dist > dist[curr.id]) continue;if (curr.id == end) break;for (Edge e : adj.get(curr.id)) {if (dist[curr.id] + e.weight < dist[e.to]) {dist[e.to] = dist[curr.id] + e.weight;pq.add(new Node(e.to, dist[e.to]));}}}if (dist[end] == Integer.MAX_VALUE) System.out.println(-1);else System.out.println(dist[end]);}}